mapper.select:
SELECT wi.*, wc.`name` as categoryName, wc.parent_id as categoryParentId FROM waste_item wi LEFT JOIN waste_category wc ON wi.category_id = wc.id
and wc.id = #{param.categoryId}
and wc.name like concat('%', #{param.categoryName} ,'%')
and wi.name like concat('%', #{param.name} ,'%')
and wi.city = #{param.city}
ORDER BY wi.create_time DESC
